#!/usr/bin/env python3
"""Deploy-time chrome injection for teeccino-reports.  Owner: HubSmith.

Runs inside .github/workflows/deploy-pages.yml on the CI checkout, right before the
Pages artifact is uploaded. It inserts ONE synchronous tag as the first child of
<head> in every in-scope page:

    <script src="/teeccino-reports/assets/hub-theme.js" data-hub-native="dark|light"></script>

WHY AT DEPLOY TIME
  Most pages are regenerated by owner builders (DataOps, AgentSmith, CatalogSmith,
  CostSmith ...). Editing each builder is many cross-agent changes and one forgotten
  builder silently drops the theme. Injecting at deploy means a rebuild can never
  lose it: whatever HTML a publisher pushes, the next deploy adds the tag back.
  The source files in the repo are NOT modified (CI works on a throwaway checkout).

IDEMPOTENT: a page that already references assets/hub-theme.js is left alone.

SCOPE (excluded on purpose):
  klaviyo-previews/   email renders: must look like the email, not the site theme
  burke/ crowley/ brendon/ orinoco/   isolated portals (AGENT_STANDARDS §18) — they
                      must not load main-site assets; Burke has its own switch
  _partials/          fragments, not pages
  design/             brand style guide + storefront mockups: colors are the content
  blog-seo-preview-*  storefront render previews
  any page with <meta name="hub-theme" content="off">

`data-hub-native` is a static hint (page ground light or dark) so hub-theme.js can
hold first paint on light-native pages in Dark mode too. Wrong hint = a one-frame
flash at worst; the runtime re-detects from computed styles.

Usage:  python .github/scripts/inject_chrome.py [--root .] [--check] [-v]
  --check  report what would change, write nothing (exit 0)
"""
from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

TAG_SRC = "/teeccino-reports/assets/hub-theme.js"
EXCLUDE_PREFIXES = ("klaviyo-previews/", "burke/", "crowley/", "brendon/", "orinoco/",
                    "_partials/", "design/", ".github/", "node_modules/")
EXCLUDE_GLOBS = ("blog-seo-preview-*.html",)

HEAD_RE = re.compile(r"<head\b[^>]*>", re.I)
HTML_RE = re.compile(r"<html\b[^>]*>", re.I)
CHARSET_RE = re.compile(r"<meta\s+charset=[^>]*>", re.I)
OFF_RE = re.compile(r"<meta[^>]+name=[\"']hub-theme[\"'][^>]+content=[\"']off[\"']", re.I)
COLOR_RE = re.compile(r"#[0-9a-fA-F]{3,8}\b|rgba?\([^)]*\)")


def _lum(hexs: str) -> float | None:
    s = hexs.strip()
    if s.startswith("#"):
        h = s[1:]
        if len(h) in (3, 4):
            h = "".join(c * 2 for c in h[:3])
        if len(h) < 6:
            return None
        r, g, b = (int(h[i:i + 2], 16) for i in (0, 2, 4))
    else:
        m = re.match(r"rgba?\(([^)]*)\)", s)
        if not m:
            return None
        p = [float(x) for x in re.split(r"[\s,/]+", m.group(1).strip()) if x][:3]
        if len(p) < 3:
            return None
        r, g, b = p

    def ch(v):
        v /= 255
        return v / 12.92 if v <= 0.03928 else ((v + 0.055) / 1.055) ** 2.4
    return 0.2126 * ch(r) + 0.7152 * ch(g) + 0.0722 * ch(b)


def native_hint(html: str) -> str:
    css = "\n".join(re.findall(r"<style[^>]*>(.*?)</style>", html, re.S | re.I))[:400000]
    # strip media-gated rules (prefers-color-scheme etc.) crudely: only top-level first match matters
    root_vars = dict(re.findall(r"(--[\w-]+)\s*:\s*([^;}{]+)", (re.search(r":root\s*\{([^}]*)\}", css) or [None, ""])[1] or ""))
    m = re.search(r"(?:^|[}\s,])body\s*\{([^}]*)\}", css)
    val = None
    if m:
        bm = re.search(r"background(?:-color)?\s*:\s*([^;}]+)", m.group(1))
        if bm:
            val = bm.group(1)
    if val:
        vm = re.search(r"var\((--[\w-]+)", val)
        if vm and vm.group(1) in root_vars and not COLOR_RE.search(val):
            val = root_vars[vm.group(1)]
        cm = COLOR_RE.search(val)
        if not cm and vm and vm.group(1) in root_vars:
            cm = COLOR_RE.search(root_vars[vm.group(1)])
        if cm:
            L = _lum(cm.group(0))
            if L is not None:
                return "light" if L > 0.4 else "dark"
        if re.search(r"\b(white)\b", val):
            return "light"
    return "dark"


def in_scope(rel: str) -> bool:
    if rel.startswith(EXCLUDE_PREFIXES):
        return False
    name = rel.rsplit("/", 1)[-1]
    return not any(Path(name).match(g) for g in EXCLUDE_GLOBS)


def inject(html: str) -> tuple[str, str]:
    """Return (new_html, status). status in injected|present|off|nohead."""
    if TAG_SRC in html or "assets/hub-theme.js" in html:
        return html, "present"
    if OFF_RE.search(html):
        return html, "off"
    tag = f'<script src="{TAG_SRC}" data-hub-native="{native_hint(html)}"></script>'
    m = HEAD_RE.search(html)
    if m:
        at = m.end()
        # keep <meta charset> first (it must sit in the first 1024 bytes)
        cm = CHARSET_RE.search(html, at, at + 1500)
        if cm:
            at = cm.end()
        return html[:at] + tag + html[at:], "injected"
    m = HTML_RE.search(html)
    if m:
        return html[:m.end()] + "<head>" + tag + "</head>" + html[m.end():], "injected"
    return html, "nohead"


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--root", default=".")
    ap.add_argument("--check", action="store_true")
    ap.add_argument("-v", action="store_true")
    a = ap.parse_args()
    root = Path(a.root).resolve()
    counts: dict[str, int] = {}
    for p in sorted(root.rglob("*.html")):
        rel = p.relative_to(root).as_posix()
        if not in_scope(rel):
            counts["excluded"] = counts.get("excluded", 0) + 1
            continue
        raw = p.read_bytes()
        try:
            html = raw.decode("utf-8")
        except UnicodeDecodeError:
            counts["undecodable"] = counts.get("undecodable", 0) + 1
            continue
        new, status = inject(html)
        counts[status] = counts.get(status, 0) + 1
        if a.v and status != "present":
            print(f"{status:9} {rel}")
        if status == "injected" and not a.check:
            p.write_bytes(new.encode("utf-8"))
    print("inject_chrome:", ", ".join(f"{k}={v}" for k, v in sorted(counts.items())))
    return 0


if __name__ == "__main__":
    sys.exit(main())
